import importlib.util
from pathlib import Path
import unittest


spec = importlib.util.spec_from_file_location(
    "check_commit_metadata", Path(__file__).parent / "check-commit-metadata.py"
)
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
findings = module.findings
identity_findings = module.identity_findings


class MessageTests(unittest.TestCase):
    def assert_rule(self, text, rule):
        self.assertEqual([found_rule for found_rule, _ in findings(text)], [rule])

    def test_session_trailer(self):
        self.assert_rule(
            "fix: thing\n\nClaude-Session: https://example.test/s/1", "session trailer"
        )

    def test_session_link(self):
        self.assert_rule("Summary.\n\nhttps://claude.ai/code/session_01ABC", "session link")

    def test_co_author_trailer(self):
        self.assert_rule(
            "fix\n\nCo-authored-by: Claude <noreply@anthropic.com>", "co-author trailer"
        )

    def test_generated_footer(self):
        self.assert_rule(
            "🤖 Generated with [Claude Code](https://example.test)", "generated-by footer"
        )

    def test_one_finding_per_line(self):
        self.assertEqual(len(findings("Generated by [Claude Code](https://claude.ai/code)")), 1)

    def test_clean_text_passes(self):
        text = (
            "Codegen: refuse an unknown type (#12)\n\n"
            "Co-authored-by: Jane Doe <jane@example.com>\n"
            "See https://docs.rs/reflectapi and CONTRIBUTING.md."
        )
        self.assertEqual(findings(text), [])


class IdentityTests(unittest.TestCase):
    def test_an_agent_author_is_refused(self):
        self.assertEqual(
            identity_findings("author", "Claude", "noreply@anthropic.com"),
            [("author is an AI agent", "Claude <noreply@anthropic.com>")],
        )

    def test_an_agent_email_is_refused_under_any_name(self):
        self.assertEqual(len(identity_findings("committer", "Bot", "x@anthropic.com")), 1)

    def test_people_and_github_pass(self):
        for name, email in [
            ("Brian Thorne", "brian@partly.com"),
            ("GitHub", "noreply@github.com"),
            ("dependabot[bot]", "49699333+dependabot[bot]@users.noreply.github.com"),
            ("Claudette Smith", "claudette@example.com"),
        ]:
            self.assertEqual(identity_findings("author", name, email), [], name)


if __name__ == "__main__":
    unittest.main()
